rss.channel:
      {{ config.title }}
        {%- if term %} - {{ term.name }}
        {%- elif section and section.title %} - {{ section.title }}
        {%- endif -%}


        {%- if section -%}
          {{ section.permalink | escape_xml | safe }}
        {%- else -%}
          {{ config.base_url | escape_xml | safe }}
        {%- endif -%}

      {{ config.description }}
      Zola
      {{ lang }}

      {% if last_updated is defined %}{{ last_updated | date(format="%a, %d %b %Y %H:%M:%S %z") }}{% endif %}
      {%- for page in pages %}
      {%- if page.extra.unlisted %}{% continue %}{% endif %}
      {%- set image_base = `src="` ~ page.permalink ~ `${1}"` %}
      {%- set content = page.content
          | regex_replace(pattern=`]*>[^<]*`, rep="")
          | regex_replace(pattern=`src="([^":/][^":]*)"`, rep=image_base)
          | regex_replace(pattern=`]*)>]*) data-name="([^"]+)"`, rep=`
${3}<code${2} data-name="${3}"`)
          | replace(from="↩", to="↩︎") %}


          {{ page.title }}
          {{ page.date | date(format="%a, %d %b %Y %H:%M:%S %z") }}
          {%- if page.updated %}
          {{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
          {%- endif %}

            {%- if page.authors -%}
              {{ page.authors[0] }}
            {%- elif config.author -%}
              {{ config.author }}
            {%- else -%}
              Unknown
            {%- endif -%}

          {{ page.permalink | escape_xml | safe }}
          {{ page.permalink | escape_xml | safe }}
          {% if page.summary %}{{ page.summary }}{% else %}{{ content }}{% endif %}

      {%- endfor %}
